create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table if not exists public.user_settings(user_id uuid primary key references auth.users(id) on delete cascade,app_name text not null default 'One Thing',commitment text not null,show_time time not null default '19:00',active_days integer[] not null default array[0,1,2,3,4,5,6],reminder_mode text not null default 'relentless',voice text not null default 'direct',debt_goal numeric(14,2) not null default 0,debt_paid numeric(14,2) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.check_ins(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,check_date date not null,status text not null check(status in ('completed','skipped','excused')),source text,completed_at timestamptz,skip_reason text,gross_sales numeric(14,2) not null default 0,profit numeric(14,2) not null default 0,items_sold integer not null default 0,minutes_live integer not null default 0,notes text not null default '',created_at timestamptz not null default now(),unique(user_id,check_date));
alter table public.profiles enable row level security;alter table public.user_settings enable row level security;alter table public.check_ins enable row level security;
drop policy if exists "profile_select" on public.profiles;create policy "profile_select" on public.profiles for select to authenticated using(auth.uid()=id);
drop policy if exists "profile_update" on public.profiles;create policy "profile_update" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "settings_select" on public.user_settings;create policy "settings_select" on public.user_settings for select to authenticated using(auth.uid()=user_id);
drop policy if exists "settings_insert" on public.user_settings;create policy "settings_insert" on public.user_settings for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists "settings_update" on public.user_settings;create policy "settings_update" on public.user_settings for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "checkins_select" on public.check_ins;create policy "checkins_select" on public.check_ins for select to authenticated using(auth.uid()=user_id);
drop policy if exists "checkins_insert" on public.check_ins;create policy "checkins_insert" on public.check_ins for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists "checkins_update" on public.check_ins;create policy "checkins_update" on public.check_ins for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "checkins_delete" on public.check_ins;create policy "checkins_delete" on public.check_ins for delete to authenticated using(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1)));return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.profiles(id,display_name) select id,coalesce(raw_user_meta_data->>'display_name',split_part(email,'@',1)) from auth.users on conflict(id) do nothing;